    std::string path;
    float path_frame = -1.0f;
    float legacy_path_frame_ignored = -1.0f;
    bool has_legacy_path_frame_ignored = false;
    std::string category;
    int platform_only = 0;
    bool ps3_per_pixel = false;
    int disabled_flags = 0;
